package mz.bam.seeky.android;
import android.app.*;import android.os.*;import android.content.res.AssetManager;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class ReaderFixes5141Test {
 @Before public void assets()throws Exception{Method add=AssetManager.class.getDeclaredMethod("addAssetPath",String.class);add.setAccessible(true);add.invoke(RuntimeEnvironment.getApplication().getAssets(),System.getProperty("seeky.main.resources"));}
 @Test public void pdfMappedTextAndGlyphOffsetsMatchTheTextUsedForNarration()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();com.tom_roush.pdfbox.android.PDFBoxResourceLoader.init(c);try(PdfTextSource source=new PdfTextSource(new File(System.getProperty("seeky.pdf.fixture")),c.getCacheDir())){String plain=source.page(0);PdfGlyphs layout=source.mappedPage(0);assertEquals(plain,layout.text);assertFalse(layout.glyphs.isEmpty());assertTrue(layout.width>0&&layout.height>0);for(PdfGlyphs.Glyph g:layout.glyphs){assertTrue(g.start>=0&&g.end<=plain.length()&&g.end>g.start);assertTrue(g.right>=g.left&&g.bottom>g.top);assertTrue(g.left>=-2&&g.right<layout.width+2);}}}
 @Test public void pdfWordSelectionUsesUnicodeTextAndPageCoordinates(){java.util.List<PdfGlyphs.Glyph> boxes=new java.util.ArrayList<>();boxes.add(new PdfGlyphs.Glyph(0,7,20,30,70,12));PdfGlyphs page=new PdfGlyphs("Criação e vida.",600,800,boxes);assertEquals(0,page.at(25,35));int[] selected=page.word(3);assertEquals("Criação",page.text.substring(selected[0],selected[1]));assertEquals(-1,page.at(500,700));}
 @Test public void narrationPaintsTheReportedRangeWithoutChangingSelection()throws Exception{ReaderPlusTest fixture=new ReaderPlusTest();fixture.setup();ReaderActivity a=fixture.a;try{String value=a.bookText.getText().toString();int end=Math.min(12,value.length());SpeechEvents.publish(new SpeechEvents.State(a.uri.toString(),"paint","A ler",0,1,1,end,true,false,false));org.robolectric.Shadows.shadowOf(Looper.getMainLooper()).idle();android.text.Spannable text=(android.text.Spannable)a.bookText.getText();android.text.style.BackgroundColorSpan[] marks=text.getSpans(1,end,android.text.style.BackgroundColorSpan.class);assertTrue(marks.length>0);assertEquals(1,text.getSpanStart(marks[marks.length-1]));assertEquals(end,text.getSpanEnd(marks[marks.length-1]));android.text.Selection.setSelection(text,2,5);a.chrome.changed();assertEquals(2,a.bookText.getSelectionStart());assertEquals(5,a.bookText.getSelectionEnd());}finally{SpeechEvents.publish(new SpeechEvents.State("","","",0,0,0,false,true));fixture.close();}}
}
